DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.expense_month_approve(uuid,date,jsonb)'::regprocedure) INTO def;IF position('IF b.source_type=''recurring_rule''' IN def)=0 THEN RAISE EXCEPTION 'Bill approval anchor unavailable';END IF;def:=replace(def,'IF b.source_type=''recurring_rule''','PERFORM public.finance_advance_contract_prepare(t,b.id);IF b.source_type=''recurring_rule''');EXECUTE def;END $$;